/**
 * WARG Platform — GameCard Component
 * ===================================
 * Factory that creates a fully-featured game card DOM element.
 * Usage:
 *   const card = GameCard.create(gameObject);
 *   container.appendChild(card);
 *
 *   // Or fill an entire row at once:
 *   GameCard.renderRow('row-recent', WARG_GAMES.recent);
 */

/* eslint-disable no-var */
var GameCard = (function () {

  /* ── Mode configuration ─────────────────────────────── */
  var MODE = {
    solo: {
      label:     'Solo',
      badgeClass:'badge--solo',
      bg:        'linear-gradient(145deg,#141028 0%,#1e1840 100%)',
      glowColor: 'rgba(153,172,255,0.18)',
    },
    coop: {
      label:     'Co-op',
      badgeClass:'badge--coop',
      bg:        'linear-gradient(145deg,#081408 0%,#0e2810 100%)',
      glowColor: 'rgba(51,255,51,0.14)',
    },
    pvp: {
      label:     'PvP',
      badgeClass:'badge--pvp',
      bg:        'linear-gradient(145deg,#180808 0%,#2a0e0e 100%)',
      glowColor: 'rgba(255,107,107,0.18)',
    },
    live: {
      label:     'Live',
      badgeClass:'badge--live',
      bg:        'linear-gradient(145deg,#141000 0%,#241e00 100%)',
      glowColor: 'rgba(255,209,102,0.18)',
    },
  };

  /* ── SVG icon strings ───────────────────────────────── */
  var ICONS = {
    thumbUp: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2',
      ' 2 0 0 0-2-2.3H14z"/>',
      '<path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/>',
      '</svg>',
    ].join(''),

    thumbDown: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2',
      ' 2 0 0 0 2 2.3H10z"/>',
      '<path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/>',
      '</svg>',
    ].join(''),

    flag: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/>',
      '<line x1="4" y1="22" x2="4" y2="15"/>',
      '</svg>',
    ].join(''),

    star: [
      '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"',
      ' aria-hidden="true">',
      '<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02',
      ' 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>',
      '</svg>',
    ].join(''),

    location: [
      '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/>',
      '<circle cx="12" cy="10" r="3"/>',
      '</svg>',
    ].join(''),

    publish: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>',
      '<polyline points="17 8 12 3 7 8"/>',
      '<line x1="12" y1="3" x2="12" y2="15"/>',
      '</svg>',
    ].join(''),

    unpublish: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>',
      '<polyline points="7 16 12 21 17 16"/>',
      '<line x1="12" y1="21" x2="12" y2="9"/>',
      '</svg>',
    ].join(''),
  };

  /* ── Helpers ────────────────────────────────────────── */
  function formatCount(n) {
    if (!n) return '0';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
    return String(n);
  }

  function buildProgressHTML(game) {
    if (game.progress == null) {
      return '<span class="gc-progress__label gc-progress__label--idle">Not started</span>';
    }
    if (game.progress >= 100) {
      return '<span class="gc-progress__label gc-progress__label--done">✓ Completed</span>';
    }
    return [
      '<div class="gc-progress__track"',
      ' role="progressbar"',
      ' aria-valuenow="' + game.progress + '"',
      ' aria-valuemin="0"',
      ' aria-valuemax="100"',
      ' aria-label="' + (game.progressLabel || game.progress + '% complete') + '">',
      '  <div class="gc-progress__fill" style="width:' + game.progress + '%"></div>',
      '</div>',
      '<span class="gc-progress__label">' + (game.progressLabel || game.progress + '% done') + '</span>',
    ].join('');
  }

  /* ── Card factory ────────────────────────────────────── */
  /**
   * create(game) → HTMLElement
   * Accepts a game data object and returns a ready-to-append article element.
   */
  function create(game, options) {
    options = options || {};
    var hideProgress  = options.hideProgress || false;
    var showPublish   = options.showPublish || false;
    var showUnpublish = options.showUnpublish || false;

    var mode    = MODE[game.mode] || MODE.solo;
    var article = document.createElement('article');

    article.className = 'game-card' + (game.featured ? ' game-card--featured' : '');
    article.dataset.gameId = game.id;
    article.tabIndex  = 0;
    article.setAttribute('role', 'listitem');
    article.setAttribute('aria-label', game.title + ' — ' + mode.label + ' game');

    /* Cover: image or emoji placeholder */
    var coverMediaHTML = game.image
      ? '<img src="' + game.image + '" alt="' + game.title + '" loading="lazy" />'
      : '<span class="gc-cover__emoji" aria-hidden="true">' + (game.emoji || '🎮') + '</span>';

    article.innerHTML = [

      /* ── Cover ── */
      '<div class="gc-cover" style="background:' + mode.bg + ';--card-glow:' + mode.glowColor + '">',
        coverMediaHTML,
        '<span class="gc-cover__badge ' + mode.badgeClass + '">' + mode.label + '</span>',
      '</div>',

      /* ── Body ── */
      '<div class="gc-body">',

        /* Title */
        '<h3 class="gc-title">' + game.title + '</h3>',

        /* Caption */
        '<p class="gc-caption">' + game.caption + '</p>',

        /* Progress */
        (hideProgress ? '' : (
          '<div class="gc-progress">' +
            buildProgressHTML(game) +
          '</div>'
        )),

        /* Author */
        '<div class="gc-author">',
          '<span class="gc-author__avatar" aria-hidden="true">' + game.author.initials + '</span>',
          '<span class="gc-author__name">' + game.author.name + '</span>',
        '</div>',

        /* Actions */
        '<div class="gc-actions">',

          (showPublish ? (
            '<button class="gc-action gc-action--publish" data-action="publish"' +
            ' aria-label="Publish game" style="width: 100%; justify-content: center; gap: var(--space-2); color: var(--color-success); border-color: rgba(51, 255, 51, 0.2);">' +
              ICONS.publish +
              '<span class="gc-action__count">Publish WARG</span>' +
            '</button>'
          ) : showUnpublish ? (
            '<button class="gc-action gc-action--unpublish" data-action="unpublish"' +
            ' aria-label="Unpublish game" style="width: 100%; justify-content: center; gap: var(--space-2); color: var(--color-warning); border-color: rgba(255, 209, 102, 0.2);">' +
              ICONS.unpublish +
              '<span class="gc-action__count">Unpublish WARG</span>' +
            '</button>'
          ) : (
            '<button class="gc-action" data-action="like"' +
            ' aria-label="Like" aria-pressed="false">' +
              ICONS.thumbUp +
              '<span class="gc-action__count">' + formatCount(game.likes) + '</span>' +
            '</button>' +

            '<button class="gc-action" data-action="dislike"' +
            ' aria-label="Dislike" aria-pressed="false">' +
              ICONS.thumbDown +
              '<span class="gc-action__count">' + formatCount(game.dislikes) + '</span>' +
            '</button>' +

            '<button class="gc-action gc-action--flag" data-action="flag"' +
            ' aria-label="Flag content" aria-pressed="false">' +
              ICONS.flag +
            '</button>' +

            '<div class="gc-rating" aria-label="Rating: ' + game.rating + ' out of 5">' +
              ICONS.star +
              '<span>' + game.rating.toFixed(1) + '</span>' +
            '</div>'
          )),

        '</div>', /* gc-actions */

      '</div>', /* gc-body */

    ].join('');

    /* ── Wire interaction ── */
    _attachEvents(article, game);

    return article;
  }

  /* ── Event handling ─────────────────────────────────── */
  function _attachEvents(article) {
    /* Action buttons: like / dislike / flag (mutually exclusive: like ↔ dislike) */
    article.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-action]');
      if (!btn) {
        /* Clicking the card body opens the game */
        _onCardOpen(article);
        return;
      }
      e.stopPropagation();

      var action = btn.dataset.action;

      if (action === 'publish' || action === 'unpublish') {
        article.dispatchEvent(new CustomEvent('warg:' + action, {
          bubbles: true,
          detail: { 
            gameId: article.dataset.gameId, 
            gameTitle: article.querySelector('.gc-title').textContent 
          }
        }));
        return;
      }

      var argId = article.dataset.gameId;

      if (action === 'flag') {
        if (typeof window.FlagModal !== 'undefined') {
          // Use a singleton flag modal instance for GameCard
          if (!window._gameCardFlagModal) window._gameCardFlagModal = new window.FlagModal();
          window._gameCardFlagModal.open(argId, 'Report Game');
        } else {
          // Dynamically import the module (relative to the HTML page loading it)
          import('./scripts/components/FlagModal.js?v=2').then(module => {
            if (!window._gameCardFlagModal) window._gameCardFlagModal = new module.FlagModal();
            window._gameCardFlagModal.open(argId, 'Report Game');
          }).catch(err => {
            console.error('[GameCard] Failed to load FlagModal:', err);
          });
        }
        return; // Don't toggle state on flag button
      }

      var isPressed = btn.getAttribute('aria-pressed') === 'true';

      btn.setAttribute('aria-pressed', String(!isPressed));
      btn.classList.toggle('is-active', !isPressed);

      /* Mutual exclusion: liking removes dislike state and vice-versa */
      if (action === 'like' && !isPressed) {
        var dislike = article.querySelector('[data-action="dislike"]');
        if (dislike && dislike.getAttribute('aria-pressed') === 'true') {
          dislike.setAttribute('aria-pressed', 'false');
          dislike.classList.remove('is-active');
        }
      } else if (action === 'dislike' && !isPressed) {
        var like = article.querySelector('[data-action="like"]');
        if (like && like.getAttribute('aria-pressed') === 'true') {
          like.setAttribute('aria-pressed', 'false');
          like.classList.remove('is-active');
        }
      }

      // Fire API call
      if (typeof api !== 'undefined' && api.voteArg) {
        api.voteArg(argId, action).then(res => {
          if (res && res.success) {
            // Update counts in DOM
            var likeCount = article.querySelector('[data-action="like"] .gc-action__count');
            var dislikeCount = article.querySelector('[data-action="dislike"] .gc-action__count');
            if (likeCount) likeCount.textContent = formatCount(res.like_count);
            if (dislikeCount) dislikeCount.textContent = formatCount(res.dislike_count);
          }
        }).catch(err => {
          console.error('[GameCard] Failed to vote:', err);
        });
      }
    });

    /* Keyboard: Enter / Space activates the card (not a button) */
    article.addEventListener('keydown', function (e) {
      if ((e.key === 'Enter' || e.key === ' ') && e.target === article) {
        e.preventDefault();
        _onCardOpen(article);
      }
    });
  }

  function _onCardOpen(article) {
    var title = article.querySelector('.gc-title');
    var gameId = article.dataset.gameId;
    console.log('[WARG] Open game:', title ? title.textContent.trim() : gameId);
    if (window.location.pathname.includes('studio.html')) {
      window.location.href = 'edit_warg.html?id=' + gameId;
    } else {
      window.location.href = 'game.html?id=' + gameId;
    }
  }

  /* ── renderRow helper ────────────────────────────────── */
  /**
   * renderRow(containerId, gamesArray)
   * Clears the container and appends freshly-built cards.
   *
   * @param {string}   containerId  — id attribute of the .card-row element
   * @param {object[]} games        — array of game data objects
   * @param {object}   options      — configuration options (e.g. hideProgress)
   */
  function renderRow(containerId, games, options) {
    var container = document.getElementById(containerId);
    if (!container) {
      console.warn('[GameCard] Container not found:', containerId);
      return;
    }
    /* DocumentFragment batches DOM insertions for one reflow */
    var frag = document.createDocumentFragment();
    games.forEach(function (game) { frag.appendChild(create(game, options)); });
    container.innerHTML = '';
    container.appendChild(frag);
  }

  /* ── renderSkeletons helper ────────────────────────────── */
  function renderSkeletons(containerId, count) {
    count = count || 5;
    var container = document.getElementById(containerId);
    if (!container) return;
    var skeletons = '';
    for (var i = 0; i < count; i++) {
      skeletons += '<div class="game-card game-card--skeleton" aria-hidden="true">' +
        '<div class="gc-cover" style="background:var(--color-surface-2)"></div>' +
        '<div class="gc-body">' +
          '<div class="skeleton-line skeleton-line--title"></div>' +
          '<div class="skeleton-line skeleton-line--caption"></div>' +
          '<div class="skeleton-line skeleton-line--caption" style="width:60%"></div>' +
        '</div>' +
      '</div>';
    }
    container.innerHTML = skeletons;
  }

  /* ── Public API ─────────────────────────────────────── */
  return { create: create, renderRow: renderRow, renderSkeletons: renderSkeletons };

}());

/**
 * WARG Platform — Home Page Script
 * Handles: sidebar/right-panel toggle (desktop collapse + mobile drawer),
 * overlay backdrop, search interactions, friends filtering, notifications.
 */

/* ── Elements ── */
const appShell        = document.getElementById('app-shell');
const sidebar         = document.getElementById('sidebar');
const rightPanel      = document.getElementById('right-panel');
const overlay         = document.getElementById('drawer-overlay');

const btnSidebarToggle    = document.getElementById('btn-sidebar-toggle');
const btnSidebarClose     = document.getElementById('btn-sidebar-close');
const btnRightPanelToggle = document.getElementById('btn-right-panel-toggle');
const btnRightPanelClose  = document.getElementById('btn-right-panel-close');

/* ── Breakpoint: is this a mobile/tablet viewport? ── */
const isMobile = () => window.matchMedia('(max-width: 1023px)').matches;

/* ── Overlay helpers ── */
function showOverlay() {
  overlay.classList.add('is-visible');
  overlay.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden'; // prevent body scroll while drawer open
}

function hideOverlay() {
  overlay.classList.remove('is-visible');
  overlay.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
}

/* ── Left Sidebar ── */
function openSidebar() {
  if (isMobile()) {
    sidebar.classList.add('drawer-open');
    showOverlay();
    btnSidebarToggle.setAttribute('aria-expanded', 'true');
  } else {
    appShell.classList.remove('sidebar-collapsed');
    btnSidebarToggle.setAttribute('aria-expanded', 'true');
  }
}

function closeSidebar() {
  if (isMobile()) {
    sidebar.classList.remove('drawer-open');
    if (!rightPanel || !rightPanel.classList.contains('drawer-open')) hideOverlay();
    btnSidebarToggle.setAttribute('aria-expanded', 'false');
  } else {
    appShell.classList.add('sidebar-collapsed');
    btnSidebarToggle.setAttribute('aria-expanded', 'false');
  }
}

function toggleSidebar() {
  if (isMobile()) {
    sidebar.classList.contains('drawer-open') ? closeSidebar() : openSidebar();
  } else {
    appShell.classList.contains('sidebar-collapsed') ? openSidebar() : closeSidebar();
  }
}

/* ── Right Panel ── */
function openRightPanel() {
  if (isMobile()) {
    rightPanel.classList.add('drawer-open');
    showOverlay();
    btnRightPanelToggle.setAttribute('aria-expanded', 'true');
  } else {
    appShell.classList.remove('right-collapsed');
    btnRightPanelToggle.setAttribute('aria-expanded', 'true');
  }
}

function closeRightPanel() {
  if (isMobile()) {
    rightPanel.classList.remove('drawer-open');
    if (!sidebar.classList.contains('drawer-open')) hideOverlay();
    btnRightPanelToggle.setAttribute('aria-expanded', 'false');
  } else {
    appShell.classList.add('right-collapsed');
    btnRightPanelToggle.setAttribute('aria-expanded', 'false');
  }
}

function toggleRightPanel() {
  if (isMobile()) {
    rightPanel.classList.contains('drawer-open') ? closeRightPanel() : openRightPanel();
  } else {
    appShell.classList.contains('right-collapsed') ? openRightPanel() : closeRightPanel();
  }
}

/* ── Wire up buttons ── */
btnSidebarToggle?.addEventListener('click', toggleSidebar);
btnSidebarClose?.addEventListener('click', closeSidebar);
btnRightPanelToggle?.addEventListener('click', toggleRightPanel);
btnRightPanelClose?.addEventListener('click', closeRightPanel);

/* Dismiss drawers when tapping overlay */
overlay?.addEventListener('click', () => {
  closeSidebar();
  closeRightPanel();
});

/* Dismiss with Escape key */
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    closeSidebar();
    closeRightPanel();
  }
});

/* ── Adapt state on viewport resize ── */
// When going from mobile → desktop, clean up drawer classes
window.addEventListener('resize', () => {
  if (!isMobile()) {
    if (sidebar) sidebar.classList.remove('drawer-open');
    if (rightPanel) rightPanel.classList.remove('drawer-open');
    if (overlay) hideOverlay();
  }
});

/* ── Navigation: active state ── */
const navItems = document.querySelectorAll('.nav-item');

navItems.forEach(item => {
  item.addEventListener('click', e => {
    // Close sidebar drawer after nav on mobile
    if (isMobile()) closeSidebar();

    navItems.forEach(n => {
      n.classList.remove('active');
      n.removeAttribute('aria-current');
    });
    item.classList.add('active');
    item.setAttribute('aria-current', 'page');
  });
});

/* ── Search: focus expansion ── */
const searchInput = document.getElementById('search-input');

searchInput?.addEventListener('focus', () => {
  searchInput.closest('.topbar__search')?.style.setProperty('max-inline-size', '560px');
});
searchInput?.addEventListener('blur', () => {
  searchInput.closest('.topbar__search')?.style.removeProperty('max-inline-size');
});

/* '/' shortcut to focus search */
document.addEventListener('keydown', e => {
  const tag = document.activeElement.tagName.toLowerCase();
  if (e.key === '/' && tag !== 'input' && tag !== 'textarea') {
    e.preventDefault();
    searchInput?.focus();
  }
});

/* ── Friends search: live filter ── */
const friendsSearchInput = document.getElementById('friends-search-input');

friendsSearchInput?.addEventListener('input', () => {
  const query = friendsSearchInput.value.toLowerCase().trim();
  const friendItems = document.querySelectorAll('.friend-item');
  friendItems.forEach(item => {
    const name = item.querySelector('.friend-item__name')?.textContent.toLowerCase() ?? '';
    item.closest('li').style.display = (!query || name.includes(query)) ? '' : 'none';
  });
});

/* ── Notification badge clear ── */
const notifBtn = document.getElementById('btn-notifications');
notifBtn?.addEventListener('click', () => {
  if (notifBtn.dataset.count) {
    notifBtn.removeAttribute('data-count');
    notifBtn.setAttribute('aria-label', 'Notifications');
  }
});

/* ── Initialize Data from API ── */



function showRowEmpty(rowId, message) {
  var container = document.getElementById(rowId);
  if (!container) return;
  container.innerHTML = '<p class="row-empty-msg">' + (message || 'No games found.') + '</p>';
}

async function initHomeData() {
  // If we are not on the home page, exit early to prevent container null errors
  if (!document.getElementById('row-recent')) return;

  if (typeof api === 'undefined') {
    console.error('API not loaded'); return;
  }

  // Show skeletons immediately
  GameCard.renderSkeletons('row-recent', 4);
  GameCard.renderSkeletons('row-new', 4);
  GameCard.renderSkeletons('row-creators', 4);

  // Fetch ARGs (public) and current user (optional) in parallel
  var results = await Promise.allSettled([
    api.getArgs(),
    api.getCurrentUser()
  ]);

  var args = results[0].status === 'fulfilled' ? results[0].value : [];
  var currentUser = results[1].status === 'fulfilled' ? results[1].value : null;

  // ── Update topbar avatar & user-gated UI ──
  if (currentUser) {
    var avatarBtn = document.getElementById('btn-profile');
    if (avatarBtn) {
      var img = avatarBtn.querySelector('img');
      if (img) {
        img.src = 'https://api.dicebear.com/9.x/identicon/svg?seed=' +
          encodeURIComponent(currentUser.username) + '&backgroundColor=1a1816';
        img.alt = currentUser.username + ' avatar';
      }
    }

    // Fetch user profile for stats
    try {
      var profile = await api.getUserProfile(currentUser.user_id);
      var statPoints = document.querySelector('.stat-block__value--green');
      if (statPoints) statPoints.textContent = (profile.total_points || 0).toLocaleString();
      var statDist = document.querySelector('[data-stat="distance"]');
      if (statDist) statDist.textContent = Math.round((profile.distance_walked_m || 0) / 1000) + ' km';
    } catch (_) { /* profile stats are non-critical */ }

    // Fetch and render friends
    try {
      var friends = await api.getFriends(currentUser.user_id);
      renderFriends(friends);
    } catch (err) {
      console.error('Failed to fetch friends', err);
    }

    // Fetch active sessions for "Recently Played"
    var sessionArgIds = new Set();
    try {
      var sessions = await api.getActiveSessions(currentUser.user_id);
      sessions.forEach(function (s) {
        if (s.Arg && s.Arg.arg_id) sessionArgIds.add(String(s.Arg.arg_id));
      });
    } catch (_) { /* fallback handled below */ }

    // Recently Played = ARGs with an active session, fall back to newest
    var recentArgs = sessionArgIds.size > 0
      ? args.filter(function (a) { return sessionArgIds.has(a.id); })
      : args.slice().sort(function (a, b) {
          return new Date(b._raw.updated_at) - new Date(a._raw.updated_at);
        }).slice(0, 10);

    if (recentArgs.length === 0) {
      showRowEmpty('row-recent', 'No games played yet.');
    } else {
      GameCard.renderRow('row-recent', recentArgs);
    }
  } else {
    // Guest: show "My Progress" prompt
    var activityCard = document.querySelector('.activity-card__stats');
    if (activityCard) {
      activityCard.innerHTML =
        '<p style="color:var(--color-text-muted);font-size:var(--font-size-caption);text-align:center;padding:var(--space-3) 0">' +
        '<a href="login.html" style="color:var(--color-accent)">Log in</a> to track your progress and recent games.</p>';
    }

    // Guest: show login prompt for friends list
    var onlineList = document.getElementById('online-friends-list');
    var offlineList = document.getElementById('offline-friends-list');
    if (onlineList) onlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">Log in to see friends</li>';
    if (offlineList) offlineList.innerHTML = '';

    // Guest recently played = newest ARGs
    var newestArgs = args.slice().sort(function (a, b) {
      return new Date(b._raw.created_at) - new Date(a._raw.created_at);
    }).slice(0, 10);

    if (newestArgs.length === 0) {
      showRowEmpty('row-recent', 'No games available yet.');
    } else {
      GameCard.renderRow('row-recent', newestArgs);
    }
  }

  // ── New & Trending — sorted by created_at desc ──
  var trendingArgs = args.slice().sort(function (a, b) {
    return new Date(b._raw.created_at) - new Date(a._raw.created_at);
  }).slice(0, 10);
  if (trendingArgs.length === 0) {
    showRowEmpty('row-new', 'No new games yet.');
  } else {
    GameCard.renderRow('row-new', trendingArgs);
  }

  // ── From Creators — sorted by play_count desc ──
  var creatorsArgs = args.slice().sort(function (a, b) {
    return (b._raw.play_count || 0) - (a._raw.play_count || 0);
  }).slice(0, 10);
  if (creatorsArgs.length === 0) {
    showRowEmpty('row-creators', 'No games available yet.');
  } else {
    GameCard.renderRow('row-creators', creatorsArgs);
  }
  // Init horizontal scroll for cards
  initCardScrolls();
}

function renderFriends(friends) {
  const onlineList = document.getElementById('online-friends-list');
  const offlineList = document.getElementById('offline-friends-list');
  const onlineCount = document.getElementById('online-friends-count');
  
  if (!onlineList || !offlineList) return;

  onlineList.innerHTML = '';
  offlineList.innerHTML = '';

  let onlineFriends = 0;

  friends.forEach(friend => {
    const isOnline = friend.GameSessions && friend.GameSessions.length > 0;
    const session = isOnline ? friend.GameSessions[0] : null;
    const gameTitle = session && session.Arg ? session.Arg.title : 'an unknown game';
    
    const activityText = isOnline ? `Playing: ${gameTitle}` : 'Offline';
    const statusClass = isOnline ? 'status--online' : 'status--offline';
    
    const initials = (friend.username || '??').substring(0, 2).toUpperCase();
    
    let avatarImg;
    if (friend.avatar) {
      // Assuming avatar is returned as base64 or buffer. If buffer, we might need different handling. 
      // Dicebear is used natively as fallback.
      avatarImg = `<div class="friend-item__avatar-img" aria-hidden="true">${initials}</div>`;
    } else {
      avatarImg = `<div class="friend-item__avatar-img" aria-hidden="true">${initials}</div>`;
    }

    const li = document.createElement('li');
    li.innerHTML = `
      <div class="friend-item" role="button" tabindex="0" aria-label="${friend.username} is ${activityText}">
        <div class="friend-item__avatar">
          ${avatarImg}
          <span class="friend-item__status-dot ${statusClass}" aria-label="${isOnline ? 'Online' : 'Offline'}"></span>
        </div>
        <div class="friend-item__info">
          <div class="friend-item__name">${friend.username}</div>
          <div class="friend-item__activity">${activityText}</div>
        </div>
        <button class="friend-item__action" aria-label="Invite ${friend.username} to a game">Invite</button>
      </div>
    `;

    if (isOnline) {
      onlineList.appendChild(li);
      onlineFriends++;
    } else {
      offlineList.appendChild(li);
    }
  });

  if (onlineCount) onlineCount.textContent = onlineFriends;

  if (onlineFriends === 0) {
    onlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">No friends online</li>';
  }
  if (friends.length - onlineFriends === 0) {
    offlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">No offline friends</li>';
  }
}

